import fs from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '..');
const clean = value => String(value ?? '').replace(/\s+/g, ' ').trim();
const norm = value => clean(value).toLowerCase().replace(/[^a-z0-9]+/g, ' ');
const esc = value => clean(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;');
const q = (skill, question, correct, wrong, explanation, hint, stage='core') => ({skill,question,correct,wrong,explanation,hint,stage});

function u01Items(rows) {
  return rows.flatMap((r, i) => [
    q('identify variables',`${r.setup} Which physical condition is deliberately changed?`,r.changed,[r.measured,r.control,'the species being studied'],`${r.changed} is the changed variable; it is deliberately given different levels.`,`Ask what the investigator deliberately varies.`,i<2?'foundation':'core'),
    q('measure growth or survival',`${r.setup} Which result should be measured to answer the question?`,r.measured,[r.changed,r.control,'the colour of the container'],`${r.measured} is the outcome that shows the organism's response.`,`Choose an observable outcome, not the condition being changed.`,i<2?'foundation':'core'),
    q('control conditions',`${r.setup} Why must ${r.control} be kept the same?`,`So differences in ${r.measured} can be linked more confidently to ${r.changed}.`,[`So every organism gives exactly the same result.`,`To make ${r.changed} change by itself.`,`To prove no other factor ever affects the organism.`],`Controlling ${r.control} makes the comparison fairer; it does not remove all natural variation.`,`A control makes groups comparable; it does not guarantee identical results.`,'core'),
    q('interpret evidence',`${r.result} Which conclusion is best supported?`,r.conclusion,[`The changed condition is the only factor that can ever affect this species.`,`Every organism will respond in exactly the same way.`,`The result proves the same pattern in every habitat.`],`${r.conclusion} This wording stays within the evidence and does not turn a pattern into an absolute rule.`,`Prefer a qualified claim that names the measured condition and response.`,'application'),
    q('reasoned prediction',`${r.setup} What is the most reasonable prediction?`,r.prediction,[`All groups will have exactly the same ${r.measured}.`,`Every organism will die in every treatment.`,`The container colour will determine the result.`],`${r.prediction} The prediction links the changed physical condition to a measurable response.`,`Use the scientific relationship and name the likely measurable outcome.`,'application'),
    q('evaluate limitations',`${r.result} What most limits a claim that ${r.changed} alone caused the pattern?`,r.limit,[`The investigation recorded a measurable outcome.`,`The groups contained the same species.`,`The result was written in a table.`],`${r.limit} A competing change or weak sampling prevents a single-cause conclusion.`,`Look for another factor that changed or evidence that was too limited.`,'challenge')
  ]);
}

function u02Items(rows) {
  return rows.flatMap((r, i) => [
    q('match motion and phenomenon',`${r.context} Which movement is mainly responsible?`,r.motion,[r.alt1,r.alt2,'a monthly change in Earth’s axial tilt'],`${r.motion} ${r.explain}`,`Separate rotation, revolution and the fixed axial tilt.`,i<2?'foundation':'core'),
    q('causal explanation',`${r.context} Which explanation is scientifically accurate?`,r.explain,[r.misconception,'The Sun travels around Earth once each day.','Earth changes the direction of its tilt every month.'],r.explain,`Choose a cause-and-effect statement, not just a label.`,i<2?'foundation':'core'),
    q('model interpretation',`${r.model} What does this model represent well?`,r.represents,[r.limit,'The exact sizes and distances of every object.','Proof that the model can predict all weather.'],`${r.represents} Models highlight selected relationships rather than copying every feature of reality.`,`Identify the feature deliberately shown by the model.`,'core'),
    q('model limitation',`${r.model} Which limitation should be stated?`,r.limit,[r.represents,'It cannot use arrows or labels.','It proves Earth is stationary.'],`${r.limit} A useful model can still omit scale, time or three-dimensional motion.`,`Ask what the representation cannot show accurately.`,'application'),
    q('reject misconception',`A student claims, “${r.misconception}” Which correction is best?`,r.correction,[`The claim is correct for every place on Earth.`,`The Moon causes the pattern instead.`,`Earth’s tilt reverses direction at each solstice.`],r.correction,`Name the actual motion and explain the observable effect.`,'application'),
    q('predict cyclic pattern',`${r.predictContext} What should the model predict?`,r.prediction,[`A permanent end to the cycle.`,`The same lighting at every location and time.`,`A random change unrelated to Earth’s motion.`],`${r.prediction} Cyclic phenomena follow repeatable motion and orientation.`,`Track what changes as Earth rotates or revolves while its axis remains tilted.`,'challenge')
  ]);
}

function u03Items(rows) {
  return rows.flatMap((r, i) => [
    q('complete circuit',`${r.context} What must be true for the device to operate?`,r.path,[`The switch must create new electricity.`,`The current must stop at the device.`,`Every part must be made of plastic.`],`${r.path} A working simple circuit needs an unbroken conducting path.`,`Trace one continuous path from one cell terminal back to the other.`,i<2?'foundation':'core'),
    q('component function',`${r.context} What is the main role of ${r.component}?`,r.role,[`It creates matter inside the circuit.`,`It uses up all current before it returns to the cell.`,`It replaces the need for a complete path.`],r.role,`Describe what the component does in the circuit, not where it is drawn.`,i<2?'foundation':'core'),
    q('energy transformation',`${r.context} Which energy transformation occurs in the load?`,r.transform,[`light energy to chemical energy only`,`sound energy to stored gravitational energy`,`no energy transfer or transformation`],`${r.transform} The cell supplies energy that the load changes into observable forms.`,`Identify the useful output and any noticeable heat.`,'core'),
    q('conductors and insulators',`${r.materialContext} Which design choice is best and why?`,r.materialAnswer,[`Use bare metal everywhere because safety is irrelevant.`,`Use plastic as the conducting core because all solids conduct equally.`,`Remove the conducting path and expect the device to work.`],r.materialExplain,`Separate the conducting core from the insulating safety covering.`,'application'),
    q('diagnose evidence',`${r.fault} What is the best first explanation?`,r.diagnosis,[`The device has used up all current permanently.`,`The switch has destroyed electrical energy.`,`Current can jump any gap without a conductor.`],r.diagnosisExplain,`Use the observation to locate a break, poor contact or unsuitable material.`,'application'),
    q('fair investigation',`${r.compare} Which method gives the fairest evidence?`,r.fair,[`Change the cell, wires and load at the same time.`,`Use one trial and assume it applies to every circuit.`,`Choose the result that matches the prediction and ignore the rest.`],`${r.fair} Changing one factor and repeating the test makes the comparison more dependable.`,`Keep all factors except the tested one the same.`,'challenge')
  ]);
}

function u04Items(rows) {
  return rows.flatMap((r, i) => [
    q('classify change',`${r.context} How should this change be classified?`,r.classification,[r.opposite,'irreversible only because it takes time','impossible to classify because all changes are identical'],`${r.classification} ${r.reason}`,`Decide whether a new substance forms; do not rely only on appearance.`,i<2?'foundation':'core'),
    q('use evidence',`${r.context} Which observation is the strongest evidence for the classification?`,r.evidence,[`The material was observed by a student.`,`The container had a different shape.`,`The change happened on a Tuesday.`],`${r.evidence} This evidence addresses whether the original substance remains or a new substance forms.`,`Select evidence about substance identity or a reversible physical process.`,i<2?'foundation':'core'),
    q('recovery or reversal',`${r.context} Which follow-up action best investigates this change?`,r.action,[`Rename the material.`,`Add food colouring and assume it is restored.`,`Record no observations and guess.`],`${r.action} This action tests reversibility, recovery, properties or the conditions involved in the change.`,`Choose a method directly linked to the change and the evidence needed.`,'core'),
    q('particle reasoning',`${r.context} Which particle-level description is most appropriate at Year 6?`,r.particles,[`All particles vanish during any visible change.`,`Every physical change creates a new element.`,`Particles stop existing when a substance dissolves.`],r.particleExplain,`For a reversible physical change, the substance remains; for a chemical change, particles are rearranged into new substances.`,'application'),
    q('reject misconception',`A student says, “${r.misconception}” Which response is best?`,r.correction,[`The claim is always true without evidence.`,`Every change caused by cooling is chemical.`,`Reversibility depends only on how expensive the equipment is.`],r.correction,`Use evidence about new substances and possible physical recovery.`,'application'),
    q('evaluate evidence',`${r.uncertain} What is the most scientific conclusion?`,r.cautious,[`A new substance definitely formed because something looked different.`,`No change occurred because the student is unsure.`,`All irreversible changes can be reversed by freezing.`],`${r.cautious} Scientific classification should match the available observations and acknowledge missing evidence.`,`Choose “insufficient evidence” when the observations do not distinguish the possibilities.`,'challenge')
  ]);
}

