for (const [code, cfg] of Object.entries(meta)) {
 cfg.practice = cfg.items;
 cfg.test = unseen[code];
 cfg.worksheet = WORKSHEETS[code].map(([question,answer])=>({question,answer}));
 cfg.slides = [
  {title:'Curriculum',body:[cfg.descriptor]},
  {title:'Learning intention',body:[cfg.intention,...cfg.success]},
  ...cfg.sections.map(([title,body])=>({title,body:[body]})),
  {title:'Important questions and answers',body:cfg.qa.map(([a,b])=>`${a} ${b}`)},
  {title:'Assessment questions and review hints',body:[cfg.test[0].question,`Answer: ${cfg.test[0].correct}`,cfg.test[1].question,`Review hint: ${cfg.test[1].hint}`]},
  {title:'Exit ticket',body:[cfg.exit,`Mastery: ${cfg.mastery}`]}
 ];
}

function canonical(code, bank, raw, index) {
 const options=[raw.correct,...raw.wrong]; const correctIndex=(index+(bank==='test'?1:0))%4;
 const ordered=[...raw.wrong]; ordered.splice(correctIndex,0,raw.correct);
 return {id:`${code}-${bank==='practice'?'P':'T'}-${String(index+1).padStart(3,'0')}`,curriculum_code:code,year_level:'Year 6',subject:'science',bank,stage:raw.stage,skill:raw.skill.replace(/\s+/g,'_'),question:clean(raw.question),audio_prompt:clean(raw.question),visual:{type:'none',asset_path:'',alt_text:''},answers:ordered.map((text,i)=>({text:clean(text),is_correct:i===correctIndex})),correct_index:correctIndex,explanation:{summary:clean(raw.explanation),hint:clean(raw.hint)},difficulty:raw.stage==='foundation'?1:raw.stage==='core'?2:3,difficulty_tier:raw.stage,sequence_priority:index+1,quality_schema:'research-authored-original-v1'};
}

function wrap(value,width=72){const words=clean(value).split(' '),out=[];let line='';for(const word of words){if(!line||`${line} ${word}`.length<=width)line=line?`${line} ${word}`:word;else{out.push(line);line=word}}if(line)out.push(line);return out}
function topicBlock(code,cfg){
 const examples=cfg.practice.slice(0,6).map(x=>`<article class="curriculum-worked-example"><h3>${esc(x.skill)}</h3><p><strong>Task:</strong> ${esc(x.question)}</p><p><strong>Model reasoning:</strong> ${esc(x.explanation)}</p></article>`).join('');
 return `<details class="curriculum-topic-section topic-depth-upgrade" open id="topic-guide"><summary><strong>What students learn in ${code}</strong></summary><div class="curriculum-detail-body"><p><strong>Learning intention:</strong> ${esc(cfg.intention)}</p><p><strong>Curriculum focus:</strong> ${esc(cfg.descriptor)}</p><h3>Success criteria</h3><ul>${cfg.success.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></details>
<details class="curriculum-topic-section"><summary><strong>Key vocabulary</strong></summary><div class="curriculum-detail-body"><dl>${cfg.vocab.map(([a,b])=>`<dt><strong>${esc(a)}</strong></dt><dd>${esc(b)}</dd>`).join('')}</dl></div></details>
<details class="curriculum-topic-section" open><summary><strong>Investigation and reasoning routine</strong></summary><div class="curriculum-detail-body"><ol>${cfg.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="unit-activity-grid">${examples}</div></div></details>
<details class="curriculum-topic-section"><summary><strong>Curriculum coverage and concept boundary</strong></summary><div class="curriculum-detail-body">${cfg.sections.map(([a,b])=>`<h3>${esc(a)}</h3><p>${esc(b)}</p>`).join('')}</div></details>
<details class="curriculum-topic-section"><summary><strong>Important questions and answers</strong></summary><div class="curriculum-detail-body"><ul>${cfg.qa.map(([a,b])=>`<li><strong>${esc(a)}</strong> ${esc(b)}</li>`).join('')}</ul></div></details>
<details class="curriculum-topic-section"><summary><strong>Assessment-style questions and review hints</strong></summary><div class="curriculum-detail-body"><ul>${cfg.test.slice(0,6).map(x=>`<li>${esc(x.question)} <strong>Hint:</strong> ${esc(x.hint)}</li>`).join('')}</ul></div></details>
<details class="curriculum-topic-section"><summary><strong>Support, core and extend</strong></summary><div class="curriculum-detail-body"><ul><li><strong>Support:</strong> highlight the changed feature, observation and comparison before writing a claim.</li><li><strong>Core:</strong> solve an unseen context and justify the answer with precise evidence.</li><li><strong>Extend:</strong> evaluate a limitation, competing explanation or misleading model while staying within Year 6 science.</li></ul></div></details>
<details class="curriculum-topic-section"><summary><strong>Exit ticket and mastery evidence</strong></summary><div class="curriculum-detail-body"><p>${esc(cfg.exit)}</p><p><strong>Evidence of mastery:</strong> ${esc(cfg.mastery)}</p></div></details>
<details class="curriculum-topic-section" id="teacher-slide"><summary><strong>${code} Classroom View</strong></summary><div class="curriculum-detail-body"><p>Project the fixed, branded page-by-page lesson drawn from this topic guide.</p><a class="curriculum-button primary" href="teacher-slides/">Open Classroom View</a></div></details>`;
}
function slideSvg(code,cfg,slide,index){const title=wrap(slide.title,42);const body=slide.body.flatMap(x=>wrap(x,72).map((line,j)=>({line,bullet:j===0})));if(title.length>2||body.length>17)throw Error(`${code} slide ${index+1} overflow`);return `<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="900" viewBox="0 0 1600 900" role="img" aria-labelledby="title desc"><title id="title">${esc(slide.title)}</title><desc id="desc">${esc(slide.body.join(' '))}</desc><rect width="1600" height="900" fill="#f8fbff"/><rect width="1600" height="72" fill="#173968"/><text x="72" y="47" font-size="25" font-weight="800" fill="#fff">${code} · YEAR 6 SCIENCE</text><text x="1325" y="47" font-size="23" font-weight="700" fill="#fff">SkillrHub</text><g opacity=".055" fill="#2457d6" font-size="34" font-weight="700" transform="rotate(-18 800 450)"><text x="170" y="340">SkillrHub • skillrhub.com</text><text x="660" y="530">SkillrHub • skillrhub.com</text><text x="1010" y="720">SkillrHub • skillrhub.com</text></g>${title.map((x,j)=>`<text x="92" y="${142+j*54}" font-size="46" font-weight="800" fill="#173968">${esc(x)}</text>`).join('')}${body.map((x,j)=>`<text x="${x.bullet?112:145}" y="${255+j*34}" font-size="26" font-weight="600" fill="#17243a">${x.bullet?'• ':''}${esc(x.line)}</text>`).join('')}<line x1="72" x2="1528" y1="840" y2="840" stroke="#cad8eb"/><text x="72" y="875" font-size="22" font-weight="700" fill="#53657d">${code} • SkillrHub • skillrhub.com</text><text x="1480" y="875" text-anchor="end" font-size="22" font-weight="700" fill="#53657d">${index+1}/${cfg.slides.length}</text></svg>`}
function viewer(code,slug,count){const figs=Array.from({length:count},(_,i)=>`<figure class="slide"${i?' hidden':''}><img src="slide-${String(i+1).padStart(2,'0')}.svg" alt="Slide ${i+1}"></figure>`).join('');return `<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><title>${code} Classroom View | SkillrHub</title><link rel="canonical" href="https://skillrhub.com/year6/science/${slug}/"><!-- Teacher Display Page: fixed authored slide sequence --><style>*{box-sizing:border-box}body{margin:0;background:#eaf0f7;color:#17243a;font-family:Arial,sans-serif}.shell{max-width:1500px;margin:auto;padding:14px}.toolbar,.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.toolbar a,.toolbar button,.controls button{border:1px solid #b9c9df;border-radius:9px;background:#fff;color:#173968;padding:10px 14px;font-weight:800;text-decoration:none;cursor:pointer}.toolbar .primary,.controls button{background:#173968;color:#fff}.count{margin-left:auto;font-weight:800}.stage{background:#111827;border-radius:14px;overflow:hidden}.slide{margin:0;aspect-ratio:16/9}.slide img{display:block;width:100%;height:100%;object-fit:contain;user-select:none;-webkit-user-drag:none}.slide[hidden]{display:none}.controls{justify-content:center;margin-top:12px}@media print{body{display:none!important}}</style></head><body data-single-open><main class="shell"><nav class="toolbar"><a href="../">Topic Guide</a><a href="/quiz/year-6/science/${code.toLowerCase()}/worksheet/">Worksheet</a><a href="/quiz/year-6/science/${code.toLowerCase()}/practice/">Practice</a><a href="/quiz/year-6/science/${code.toLowerCase()}/test/">Test</a><button class="primary" id="fullscreen">Fullscreen</button><span class="count" id="count"></span></nav><section class="stage research-aligned-lesson" id="stage">${figs}</section><div class="controls"><button id="prev">Previous</button><button id="next">Next</button></div></main><script>(()=>{const s=[...document.querySelectorAll('.slide')],c=document.getElementById('count');let i=0;function show(n){i=Math.max(0,Math.min(s.length-1,n));s.forEach((x,j)=>x.hidden=j!==i);c.textContent='Slide '+(i+1)+' of '+s.length;prev.disabled=i===0;next.disabled=i===s.length-1}prev.onclick=()=>show(i-1);next.onclick=()=>show(i+1);document.onkeydown=e=>{if(e.key==='ArrowRight')show(i+1);if(e.key==='ArrowLeft')show(i-1);if((e.ctrlKey||e.metaKey)&&['c','p','s','u'].includes(e.key.toLowerCase()))e.preventDefault()};fullscreen.onclick=()=>stage.requestFullscreen?.();stage.oncontextmenu=e=>e.preventDefault();show(0)})();</script></body></html>`}

for(const [code,cfg] of Object.entries(meta)){
 if(cfg.practice.length!==48||cfg.test.length!==16||cfg.worksheet.length!==12)throw Error(`${code} counts`);
 const all=[...cfg.practice.map((x,i)=>canonical(code,'practice',x,i)),...cfg.test.map((x,i)=>canonical(code,'test',x,i))];
 if(new Set(all.map(x=>norm(x.question))).size!==64)throw Error(`${code} duplicate stems`);
 for(const item of all){if(item.answers.length!==4||new Set(item.answers.map(x=>norm(x.text))).size!==4||item.answers.filter(x=>x.is_correct).length!==1)throw Error(`${item.id} answers`)}
 const lower=code.toLowerCase();fs.writeFileSync(path.join(ROOT,`assets/assessment-banks/year6/science/${lower}.json`),JSON.stringify(all,null,2)+'\n');
 const slug=fs.readdirSync(path.join(ROOT,'year6/science')).find(x=>x.startsWith(lower+'-'));const topicPath=path.join(ROOT,'year6/science',slug,'index.html');let html=fs.readFileSync(topicPath,'utf8');const anchor=html.indexOf('id="topic-guide"'),start=html.lastIndexOf('<details',anchor),end=html.indexOf('<!-- skillr-topic-videos:start -->');if(start<0||end<start)throw Error(`${code} topic boundaries`);html=html.slice(0,start)+topicBlock(code,cfg)+'\n'+html.slice(end);fs.writeFileSync(topicPath,html);
 const slideDir=path.join(ROOT,'year6/science',slug,'teacher-slides');for(const old of fs.readdirSync(slideDir).filter(x=>/^slide-\d+\.svg$/.test(x)))fs.rmSync(path.join(slideDir,old));cfg.slides.forEach((s,i)=>fs.writeFileSync(path.join(slideDir,`slide-${String(i+1).padStart(2,'0')}.svg`),slideSvg(code,cfg,s,i)));fs.writeFileSync(path.join(slideDir,'index.html'),viewer(code,slug,cfg.slides.length));
 const wdir=path.join(ROOT,`quiz/year-6/science/${lower}/worksheet`);const w=cfg.worksheet.map((x,i)=>({id:`${lower}-w-${String(i+1).padStart(3,'0')}`,curriculumCode:code,printable:true,worksheet:true,type:'self-check',question:clean(x.question),modelAnswer:clean(x.answer),explanation:clean(x.answer)}));fs.writeFileSync(path.join(wdir,'questions.js'),`"use strict";\nwindow.skillrWorksheetQuestions = ${JSON.stringify(w,null,2)};\nwindow.quizWorksheetQuestions = window.skillrWorksheetQuestions;\n`);let wi=fs.readFileSync(path.join(wdir,'index.html'),'utf8').replace(/worksheetQuestionLimit:\d+/,'worksheetQuestionLimit:12').replace(/<script src="\/quiz\/year-6\/science\/[^\"]+\/(?:practice|worksheet)\/questions\.js"><\/script>/,`<script src="/quiz/year-6/science/${lower}/worksheet/questions.js"></script>`);if(!wi.includes('<strong>Learning focus:</strong>'))wi=wi.replace(/(<p>Use this printable homework sheet[^<]*<\/p>)/,`$1<p><strong>Learning focus:</strong> ${esc(cfg.intention)}</p>`);fs.writeFileSync(path.join(wdir,'index.html'),wi);
 console.log(`${code}: 48 Practice, 16 unseen Test, 12 Worksheet, ${cfg.slides.length} slides`);
}
